        for neighbor in get_neighbors(node[0], node[1]):
            if neighbor not in path:
                path.append(neighbor)
                result = backtrack(neighbor, path)
                if result:
                    return result
                path.pop()
        return None

    path = [start]
    result = backtrack(goal, path)
    return result if result else []
