def solve(grid, start, goal):
    def is_valid(r, c):
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def backtrack_path(path, current):
        if current == start:
            return path[::-1]
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = current[0]+dr, current[1]+dc
            if is_valid(nr, nc) and (nr, nc) in path:
                result = backtrack_path(path, (nr, nc))
                if result:
                    return result
        return None

    def dfs(r, c, path):
        if (r, c) == goal:
            return path + [(r, c)]
        path.append((r, c))
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r+dr, c+dc
            if is_valid(nr, nc) and (nr, nc) not in path:
                result = dfs(nr, nc, path)
                if result:
                    return result
        path.pop()
        return None

    # First, check if start or goal is invalid
    if not is_valid(start[0], start[1]) or not is_valid(goal[0], goal[1]):
        return []

    # Try to find a path using DFS with backtracking
    path = []
    result = dfs(start[0], start[1], path)
    if result:
        return result

    # If not found, try a different backtracking approach
    return backtrack_path([start], start)
