    def get_neighbors(row, col):
        return [(row + dr, col + dc) for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)] if is_valid(row + dr, col + dc)]

    # BFS to find the shortest path
    def bfs(start, goal):
