def solve(n, edges, s, t):
    from collections import defaultdict
    import heapq

    if s == t:
        return 0

    # Build adjacency list
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    # Dijkstra's algorithm with priority queue
    dist = [float('inf')] * n
    dist[s] = 0
