def solve(n, edges, s, t):
    from collections import deque

    if s == t:
        return 0

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Bellman-Ford algorithm to find shortest path
    # since n <= 100, Bellman-Ford is efficient enough
    dist = [float('inf')] * n
    dist[s] = 0

    # Relax all edges up to n-1 times
    for i in range(n - 1):
        for u in range(n):
            if dist[u] != float('inf'):
                for v, w in adj[u]:
                    if dist[v] > dist[u] + w:
                        dist[v] = dist[u] + w

    # Check for negative cycles (not needed for this problem since weights are non-negative)
    # But included for robustness in case of any error
    for u in range(n):
        if dist[u] != float('inf'):
            for v, w in adj[u]:
                if dist[v] > dist[u] + w:
                    if dist[v] == float('inf'):
                        dist[v] = dist[u] + w
                    else:
                        # Negative cycle detected, but we don't need to handle it for this problem
                        pass

    return dist[t] if dist[t] != float('inf') else -1
```

