def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Dijkstra's algorithm for shortest path in a directed graph with non-negative weights
    dist = [float('inf')] * n
    dist[s] = 0
    visited = [False] * n

    while True:
        # Find the node with the smallest distance that hasn't been visited
        u = -1
        min_dist = float('inf')
        for i in range(n):
            if not visited[i] and dist[i] < min_dist:
                min_dist = dist[i]
                u = i
        if u == -1:
            break  # All remaining nodes are unreachable
        visited[u] = True

        for v, w in adj[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w

    return dist[t] if dist[t] != float('inf') else -1
