def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    from collections import defaultdict
    adj = defaultdict(list)
    for u, v, w in edges:
        adj[u].append((v, w))

    # Bellman-Ford algorithm to find shortest path in a graph with possible negative weights
    # (but weights are non-negative here so Dijkstra could also be used)
    # However, Bellman-Ford is used here to handle possible negative weights if any (even though w >= 0)
    # Though in this problem, all weights are non-negative, but the algorithm is general.

    # Initialize distance array
    dist = [float('inf')] * n
    dist[s] = 0

    # Relax edges up to n-1 times
    for i in range(n - 1):
        updated = False
        for u in range(n):
            if dist[u] == float('inf'):
                continue
            for v, w in adj[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    updated = True
        if not updated:
            break  # No more updates, can break early

    return dist[t] if dist[t] != float('inf') else -1
```

