def solve(n, edges, s, t):
    # If start and target are the same, return 0
    if s == t:
        return 0

    # Build adjacency list
    from collections import defaultdict
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    # Bellman-Ford algorithm to handle negative weights and detect negative cycles
    # But since weights are non-negative (0 <= w <= 100), Dijkstra can be used
    # However, for the sake of novelty, we'll implement Bellman-Ford here for demonstration

    # Initialize distance array
    dist = [float('inf')] * n
    dist[s] = 0

    # Relax all edges up to n-1 times
    for i in range(n - 1):
        updated = False
        for u in range(n):
            if dist[u] == float('inf'):
                continue
            for v, w in graph[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    updated = True
        if not updated:
            break  # Early exit if no updates

    # Check for negative weight cycles that are reachable from s
    for u in range(n):
        if dist[u] == float('inf'):
            continue
        for v, w in graph[u]:
            if dist[v] > dist[u] + w:
                # If we can still relax, there's a negative cycle
                # But since all weights are non-negative, this is impossible
                # So we can skip this check, but including it for completeness
                pass

    # Final check for reachability
    if dist[t] == float('inf'):
        return -1
    return dist[t]
