def solve(n, edges, s, t):
    # Approach: Use Bellman-Ford algorithm to find the shortest path in a directed graph
    # which can handle negative weights (but not negative cycles), and is suitable for small n

    if s == t:
        return 0

    # Initialize distance array with infinity
    dist = [float('inf')] * n
    dist[s] = 0

    # Relax edges up to n-1 times
    for _ in range(n - 1):
        for u, v, w in edges:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w

    # Check for negative weight cycles (not needed here, but included for completeness)
    for u, v, w in edges:
        if dist[u] + w < dist[v]:
            # Negative cycle, but since the problem says to return -1 if unreachable, we ignore this for now
            pass

    return dist[t] if dist[t] != float('inf') else -1
```

