    if s == t:
        return 0

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Dijkstra's algorithm
    import heapq
    dist = [float('inf')] * n
    dist[s] = 0
    heap = [(0, s)]

    while heap:
        curr_dist, u = heapq.heappop(heap)
        if u == t:
            return curr_dist
        if curr_dist > dist[u]:
            continue
        for v, w in adj[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                heapq.heappush(heap, (dist[v], v))

    return -1
```

