def solve(n, edges, s, t):
    from collections import deque
    if s == t: return 0
    adj = [[] for _ in range(n)]
    for u, v, w in edges: adj[u].append((v, w))
    dist = [float('inf')] * n
    dist[s] = 0
    visited = [False] * n
    q = deque([s])
    while q:
        u = q.popleft()
        visited[u] = True
        for v, w in adj[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                if not visited[v]: q.append(v)
    return dist[t] if dist[t] != float('inf') else -1
