def solve(n, edges, s, t):
    if s == t:
        return 0

    # Use Bellman-Ford algorithm to find the shortest path in a graph with possible negative weights
    # Since the number of nodes is small (n <= 100), it's efficient enough
    dist = [float('inf')] * n
    dist[s] = 0

    # Relax edges up to n-1 times
    for i in range(n - 1):
        for u, v, w in edges:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w

    # Check for negative weight cycles (though not necessary for this problem, included for completeness)
    for u, v, w in edges:
        if dist[u] + w < dist[v]:
            dist[v] = float('inf')  # Mark as unreachable if a negative cycle is found

    return dist[t] if dist[t] != float('inf') else -1
